/**
 * Single source of truth for named eases. Everything else (Silia tokens, the JSX
 * `__EASE_PRESETS` block generated by scripts/copy-jsx.mjs, `ae_ease list`,
 * `motion://tokens/easings`) derives from this table.
 *
 * Numbers are facts and carry their origin in `source` / `license`. Names ending in
 * `_in` accelerate, `_out` decelerate, `_in_out` do both.
 *
 * AE mapping (see bezierToKeyframeEase): a CSS cubic-bezier(x1,y1,x2,y2) maps to
 * one KeyframeEase per side: influence_out = 100*x1, speed_out = (y1/x1)*avgSpeed;
 * influence_in = 100*(1-x2), speed_in = ((1-y2)/(1-x2))*avgSpeed. Influence is
 * clamped to AE's 0.1..100 range.
 */

export type EaseRole = "enter" | "exit" | "within" | "loop" | "any";

export interface EaseDef {
  /** cubic-bezier(x1, y1, x2, y2) */
  bezier: [number, number, number, number];
  role: EaseRole;
  source: string;
  license: string;
  /** y outside 0..1: the curve overshoots its target (AE cannot express this with a single KeyframeEase pair). */
  overshoots?: boolean;
  /** Equivalent GSAP ease name, when one exists. */
  gsap?: string;
  note?: string;
}

const SILIA = "Silia motion tokens (in production; cubic-bezier values match GSAP's CSS approximations)";
const GSAP = "GSAP ease names (numbers are the standard CSS cubic-bezier approximations of Penner's equations)";
