/** Source category for grouping (`ae_ease list`, resources). */
export function easeCategory(name: string): string {
  if (/^(carbon_)/.test(name)) return "carbon";
  if (/^(material_)/.test(name)) return "material";
  if (/^(fluent_)/.test(name)) return "fluent";
  if (/^(atlassian_)/.test(name)) return "atlassian";
  if (/^(polaris_)/.test(name)) return "polaris";
  if (/^ease_(out|in_out|in)_(quart|quint|expo|back)$/.test(name)) return "easings.net";
  return "silia/gsap";
}

export function easeNames(): string[] {
  return Object.keys(EASES);
}

export function normalizeEaseName(name: string): string {
  return String(name)
    .trim()
    .toLowerCase()
    .replace(/[.\-\s]+/g, "_")
    .replace(/^silia_/, "");
}

/** Case-insensitive lookup; accepts `.`, `-` or spaces as separators and a `silia.` prefix. */
export function resolveEase(name: string): (EaseDef & { name: string }) | undefined {
  const key = normalizeEaseName(name);
  const def = EASES[key];
  return def ? { name: key, ...def } : undefined;
}

export function clampInfluence(v: number): number {
  return Math.max(0.1, Math.min(100, v));
}

function round(n: number, d = 3): number {
  const f = Math.pow(10, d);
  return Math.round(n * f) / f;
}

/** AE influences (speed 0) for a cubic-bezier: the shape when the segment's average velocity is unknown. */
export function bezierToInfluence(bezier: readonly [number, number, number, number]): { outInfluence: number; inInfluence: number } {
  const [x1, , x2] = bezier;
  return { outInfluence: round(clampInfluence(x1 * 100)), inInfluence: round(clampInfluence((1 - x2) * 100)) };
}

export interface KeyframeEasePair {
  outInfluence: number;
  outSpeed: number;
  inInfluence: number;
  inSpeed: number;
}

/**
 * Full KeyframeEase pair for a segment whose average speed is `avgSpeed`
 * (|Δvalue| / Δt in the property's units per second).
 *   influence_out = 100*x1,      speed_out = (y1/x1)*avgSpeed
 *   influence_in  = 100*(1-x2),  speed_in  = ((1-y2)/(1-x2))*avgSpeed
 * When x1 = 0 or x2 = 1 the tangent is vertical in CSS terms; AE cannot express that, so speed is 0 and influence is clamped to 0.1.
 */
export function bezierToKeyframeEase(bezier: readonly [number, number, number, number], avgSpeed: number): KeyframeEasePair {
  const [x1, y1, x2, y2] = bezier;
  const outSpeed = x1 > 0 ? (y1 / x1) * avgSpeed : 0;
  const inSpeed = x2 < 1 ? ((1 - y2) / (1 - x2)) * avgSpeed : 0;
  return { outInfluence: round(clampInfluence(x1 * 100)), outSpeed: round(outSpeed, 4), inInfluence: round(clampInfluence((1 - x2) * 100)), inSpeed: round(inSpeed, 4) };
}

/** `cubic-bezier(x1, y1, x2, y2)` string for CSS / GSAP CustomEase. */
export function easeToCss(name: string): string {
  const e = resolveEase(name);
  if (!e) throw new Error(`Unknown ease "${name}". Known: ${easeNames().join(", ")}`);
  if (e.name === "linear") return "linear";
  return `cubic-bezier(${e.bezier.join(", ")})`;
}

/** Names grouped by category, each with bezier, role and AE influences. */
export function easesByCategory(): Record<string, Array<{ name: string; bezier: [number, number, number, number]; role: EaseRole; inInfluence: number; outInfluence: number; gsap?: string; overshoots?: boolean; note?: string; source: string; license: string }>> {
  const out: Record<string, Array<any>> = {};
  for (const [name, def] of Object.entries(EASES)) {
    const cat = easeCategory(name);
    const inf = bezierToInfluence(def.bezier);
    (out[cat] ??= []).push({ name, bezier: def.bezier, role: def.role, inInfluence: inf.inInfluence, outInfluence: inf.outInfluence, gsap: def.gsap, overshoots: def.overshoots, note: def.note, source: def.source, license: def.license });
  }
  return out;
}

